 "său, auzind despre marele Dascăl, l-a luat pe tânărul Pangratie cu "
 "sine la Ierusalim, iar văzând minunile și auzind învățătura cea "
 "dumnezeiască, a crezut în Hristos și s-a apropiat de apostoli, mai "
